      && input.internalCounts.eligibleRespondentN >= 3
      && input.internalCounts.resultContributorN === input.internalCounts.eligibleRespondentN
      && input.internalCounts.metricValidN[id] === input.internalCounts.eligibleRespondentN)
  ))

}
